import "server-only";
import { randomUUID } from "node:crypto";
import type { Prisma } from "@/generated/prisma/client";
export async function appendAudit(
  tx: Prisma.TransactionClient,
  event: {
    actorId: string;
    targetId: string | null;
    action: string;
    requestId: string;
    requestHash: string;
    reason: string;
    before: Prisma.InputJsonObject;
    after: Prisma.InputJsonObject;
  },
) {
  await tx.$executeRaw`INSERT INTO "AdminAuditLog" (id,"actorUserId","targetUserId","actorIdSnapshot","targetIdSnapshot",action,"requestId","requestHash",reason,before,after) VALUES (${randomUUID()},${event.actorId},${event.targetId},${event.actorId},${event.targetId},${event.action},${event.requestId},${event.requestHash},${event.reason},${JSON.stringify(event.before)}::jsonb,${JSON.stringify(event.after)}::jsonb)`;
}
